import 'dart:async';
import 'dart:convert';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:hyzen_pharmd/app/providers.dart';
import 'package:hyzen_pharmd/features/content/data/content_providers.dart';
import 'package:hyzen_pharmd/features/content/domain/site_models.dart';
import 'package:hyzen_pharmd/features/notifications/notifications_screen.dart';

class _Account extends Fake implements User {
  _Account(this.id);
  final String id;
  @override
  String get uid => id;
}
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  Future<ProviderContainer> account(SharedPreferences prefs, {SiteSettings? settings}) async {
    final container = ProviderContainer(overrides: [
      sharedPrefsProvider.overrideWithValue(prefs),
      authStateProvider.overrideWith((ref) => Stream.value(_Account('a'))),
      siteSettingsProvider.overrideWithValue(settings ?? SiteSettings({})),
      announcementProvider.overrideWithValue(null),
    ]);
    await container.read(authStateProvider.future);
    container.read(notificationsProvider);
    return container;
  }
  test('legacy notices migrate without replacing the original cache and archive survives restart', () async {
    final legacy = jsonEncode([{'id': 'n1', 'title': 'Lecture', 'body': 'Notes', 'category': 'academic', 'read': false}]);
    SharedPreferences.setMockInitialValues({'notifications_a': legacy});
    final prefs = await SharedPreferences.getInstance();
    final first = await account(prefs);
    final control = first.read(notificationsProvider.notifier);
    expect(await control.archive('n1', true, owner: control.key), isTrue);
    expect(prefs.getString('notifications_a'), legacy);
    first.dispose();
    final second = await account(prefs);
    addTearDown(second.dispose);
    expect(second.read(notificationsProvider).single['archived'], isTrue);
    expect(await second.read(notificationsProvider.notifier).read('n1', owner: 'notifications_a'), isTrue);
    expect(second.read(notificationsProvider).single['read'], isTrue);
  });
  test('removed active notice stays dismissed across restart and Undo restores its exact local copy', () async {
    SharedPreferences.setMockInitialValues({'notifications_a': jsonEncode([{'id': 'n1', 'title': 'Notice', 'read': false}])});
    final prefs = await SharedPreferences.getInstance();
    final first = await account(prefs);
    final removed = await first.read(notificationsProvider.notifier).remove('n1', owner: 'notifications_a');
    expect(removed, isNotNull);
    first.dispose();
    final second = await account(prefs, settings: SiteSettings({'fullScreenNotice': {'id': 'n1', 'enabled': true, 'title': 'Notice', 'body': 'Current published notice'}}));
    addTearDown(second.dispose);
    await Future<void>.delayed(Duration.zero);
    await Future<void>.delayed(Duration.zero);
    expect(second.read(notificationsProvider), isEmpty);
    expect(await second.read(notificationsProvider.notifier).restore(removed!, owner: 'notifications_a'), isTrue);
    expect(second.read(notificationsProvider).single['title'], 'Notice');
  });
  test('old-account actions cannot mark or restore another accounts notices', () async {
    SharedPreferences.setMockInitialValues({});
    final prefs = await SharedPreferences.getInstance();
    final stream = StreamController<User?>.broadcast();
    final container = ProviderContainer(overrides: [
      sharedPrefsProvider.overrideWithValue(prefs),
      authStateProvider.overrideWith((ref) => stream.stream),
      siteSettingsProvider.overrideWithValue(SiteSettings({})),
      announcementProvider.overrideWithValue(null),
    ]);
    final subscription = container.listen(authStateProvider, (_, __) {});
    final ready = container.read(authStateProvider.future);stream.add(_Account('a'));await ready;
    final old = container.read(notificationsProvider.notifier);
    await old.restore({'id': 'same-id', 'title': 'A', 'read': false}, owner: 'notifications_a');
    stream.add(_Account('b'));await Future<void>.delayed(Duration.zero);
    final current = container.read(notificationsProvider.notifier);
    await current.restore({'id': 'same-id', 'title': 'B', 'read': false}, owner: 'notifications_b');
    expect(await old.read('same-id', owner: 'notifications_a'), isFalse);
    expect(await old.restore({'id': 'private-a', 'title': 'A private'}, owner: 'notifications_a'), isFalse);
    expect(container.read(notificationsProvider).single['title'], 'B');
    expect(container.read(notificationsProvider).single['read'], isFalse);
    subscription.close();container.dispose();await stream.close();
  });
}

