  testWidgets('blog, about, contact and safe missing viewer render', (
    tester,
  ) async {
    for (final path in [
      '/blog',
      '/blog/b1',
      '/about',
      '/contact',
      '/viewer',
      '/settings',
      '/shop',
      '/cart',
      '/orders',
