import 'dart:async';
import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../app/providers.dart';
import '../../core/widgets/common.dart';
import '../../core/widgets/ui_kit.dart';
import '../../core/theme/tokens.dart';
import '../../core/utils/links.dart';
import '../academics/domain/drive.dart';
import '../content/data/content_providers.dart';

enum NotificationCategory { academic, announcements, orders }
NotificationCategory notificationCategory(Map<String, dynamic> item) => switch ('${item['category'] ?? ''}'.toLowerCase()) {
  'academic' => NotificationCategory.academic,
  'orders' || 'order' => NotificationCategory.orders,
  _ => NotificationCategory.announcements,
};
String notificationCategoryLabel(NotificationCategory category) => switch(category) {
  NotificationCategory.academic => 'Academic', NotificationCategory.announcements => 'Announcements', NotificationCategory.orders => 'Orders',
};

class NotificationsController extends Notifier<List<Map<String, dynamic>>> {
  int _generation = 0;
  bool _disposed = false;
  Set<String> _dismissed = {};
  Future<void> _tail = Future<void>.value();
  String get key => 'notifications_${ref.read(authStateProvider).valueOrNull?.uid ?? 'guest'}';
  @override
  List<Map<String, dynamic>> build() {
    ref.watch(authStateProvider.select((a) => a.valueOrNull?.uid));
    _generation++; _disposed = false;
    ref.onDispose(() => _disposed = true);
    final prefs = ref.read(sharedPrefsProvider);
    List<Map<String, dynamic>> list = [];
    _dismissed = {};
    try {
      final saved = jsonDecode(prefs.getString('${key}_v2') ?? 'null');
      if (saved is Map && saved['version'] == 1 && saved['items'] is List) {
        list = (saved['items'] as List).whereType<Map>().map((m) => Map<String, dynamic>.from(m)).take(100).toList();
        _dismissed = (saved['dismissed'] is List ? saved['dismissed'] as List : []).whereType<String>().take(100).toSet();
      } else {
        final legacy = jsonDecode(prefs.getString(key) ?? '[]');
        if (legacy is List) list = legacy.whereType<Map>().map((m) => Map<String, dynamic>.from(m)).take(100).toList();
      }
    } catch (_) {
      try { final legacy = jsonDecode(prefs.getString(key) ?? '[]'); if (legacy is List) list = legacy.whereType<Map>().map((m) => Map<String, dynamic>.from(m)).take(100).toList(); } catch (_) {}
    }
    ref.listen(announcementProvider, (_, a) {
      if (a != null) _receive({'id': 'ann_${DriveLinks.fnv1a36('${a.text}|${a.linkUrl}')}', 'title': 'From PHARM D WITH HYZEN', 'body': a.text, 'url': a.linkUrl, 'category': 'announcements'});
    }, fireImmediately: true);
    ref.listen(siteSettingsProvider, (_, s) {
      final n = s.notice;
      if (n != null && n.enabled && n.id.isNotEmpty && (n.expires == null || n.expires!.isAfter(DateTime.now()))) {
        _receive({'id': n.id, 'title': n.title, 'body': n.body, 'url': n.primaryUrl, 'image': n.image,
          'category': n.raw['category'], 'important': n.raw['important'] == true});
      }
    }, fireImmediately: true);
    return list;
  }
  Future<bool> _change(String? expectedKey, bool Function(List<Map<String,dynamic>>, Set<String>) transform) {
    final owner = expectedKey ?? key;
    final generation = _generation;
    final task = _tail.then((_) async {
      if (_disposed || owner != key || generation != _generation) return false;
      final items = state.map((m) => Map<String, dynamic>.from(m)).toList();
      final dismissed = {..._dismissed};
      if (!transform(items, dismissed)) return true;
      final kept = items.take(100).toList();
      final deleted = dismissed.toList();
      final bounded = deleted.skip(deleted.length > 100 ? deleted.length - 100 : 0).toSet();
      try {
        final ok = await ref.read(sharedPrefsProvider).setString('${owner}_v2', jsonEncode({'version': 1, 'items': kept, 'dismissed': bounded.toList()}));
        if (!ok || _disposed || owner != key || generation != _generation) return false;
        _dismissed = bounded; state = kept; return true;
      } catch (_) { return false; }
    });
    _tail = task.then<void>((_) {}, onError: (Object _, StackTrace __) {});
    return task;
  }
  void _receive(Map<String, dynamic> item) {
    final generation = _generation; final owner = key;
    Future.microtask(() {
      if (_disposed || generation != _generation || owner != key) return;
      unawaited(_change(owner, (items, dismissed) {
        final id = '${item['id'] ?? ''}';
        if (id.isEmpty || dismissed.contains(id) || items.any((m) => m['id'] == id)) return false;
        items.insert(0, {...item, 'receivedAt': DateTime.now().toIso8601String(), 'read': false}); return true;
      }).then((_) {}));
    });
  }
  Future<bool> read(String id, {String? owner}) => _change(owner, (items, _) {
    final i = items.indexWhere((m) => m['id'] == id); if (i < 0 || items[i]['read'] == true) return false;
    items[i] = {...items[i], 'read': true}; return true;
  });
  Future<bool> readAll({String? owner}) => _change(owner, (items, _) {
    var changed = false; for (var i = 0; i < items.length; i++) { if (items[i]['read'] != true) { items[i] = {...items[i], 'read': true}; changed = true; } } return changed;
  });
  Future<bool> archive(String id, bool value, {required String owner}) => _change(owner, (items, _) {
    final i = items.indexWhere((m) => m['id'] == id); if (i < 0 || (items[i]['archived'] == true) == value) return false;
    items[i] = {...items[i], 'archived': value}; return true;
  });
  Future<Map<String, dynamic>?> remove(String id, {required String owner}) async {
    Map<String, dynamic>? removed;
    final ok = await _change(owner, (items, dismissed) { final i = items.indexWhere((m) => m['id'] == id); if (i < 0) return false; removed = items.removeAt(i); dismissed.add(id); return true; });
    return ok ? removed : null;
  }
  Future<bool> restore(Map<String, dynamic> item, {required String owner}) => _change(owner, (items, dismissed) {
    final id = '${item['id'] ?? ''}'; if (id.isEmpty || items.any((m) => m['id'] == id)) return false;
    dismissed.remove(id); items.insert(0, Map<String, dynamic>.from(item)); return true;
  });
}

final notificationsProvider =
    NotifierProvider<NotificationsController, List<Map<String, dynamic>>>(
      NotificationsController.new,
    );

class NotificationBell extends ConsumerWidget {
  const NotificationBell({super.key});
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final n = ref.watch(
      notificationsProvider.select(
        (l) => l.where((m) => m['read'] != true && m['archived'] != true).length,
      ),
    );
    return IconButton(
      tooltip: 'Notifications',
      onPressed: () => context.push('/notifications'),
      icon: Badge(
        isLabelVisible: n > 0,
        label: Text(n > 9 ? '9+' : '$n'),
        child: const Icon(Icons.notifications_none_rounded),
      ),
    );
  }
}

class NotificationsScreen extends ConsumerStatefulWidget {
  const NotificationsScreen({super.key});
  @override
  ConsumerState<NotificationsScreen> createState() => _NotificationsScreenState();
}
class _NotificationsScreenState extends ConsumerState<NotificationsScreen> {
  NotificationCategory? _category;
  bool _unread = false, _archive = false;
  Future<void> _check(Future<bool> operation) async {
    final ok = await operation;
    if (!ok && mounted) showHSnack(context, 'Could not update notifications. Please retry.', error: true);
  }
  @override
  Widget build(BuildContext context) {
    final all = ref.watch(notificationsProvider);
    final controller = ref.read(notificationsProvider.notifier);
    final owner = controller.key;
    final folder = all.where((m) => (m['archived'] == true) == _archive).toList();
    final visible = folder.where((m) => (!_unread || m['read'] != true) && (_category == null || notificationCategory(m) == _category)).toList();
    final categories = NotificationCategory.values.where((c) => folder.any((m) => notificationCategory(m) == c));
    final t = Theme.of(context);
    return Scaffold(appBar: HTopBar(title: 'Notifications', actions: [TextButton(onPressed: folder.isEmpty ? null : () => _check(controller.readAll(owner: owner)), child: const Text('Read all'))]), body: Column(children: [
      Padding(padding: const EdgeInsets.symmetric(horizontal: HSpace.screen, vertical: 8), child: Wrap(spacing: 8, runSpacing: 8, children: [
        ChoiceChip(label: Text('Inbox (${all.where((m) => m['archived'] != true).length})'), selected: !_archive, onSelected: (_) => setState(() { _archive = false; _category = null; })),
        ChoiceChip(label: Text('Archived (${all.where((m) => m['archived'] == true).length})'), selected: _archive, onSelected: (_) => setState(() { _archive = true; _category = null; })),
        FilterChip(label: Text('Unread (${folder.where((m) => m['read'] != true).length})'), selected: _unread, onSelected: (v) => setState(() => _unread = v)),
      ])),
      if (categories.isNotEmpty) SingleChildScrollView(scrollDirection: Axis.horizontal, padding: const EdgeInsets.symmetric(horizontal: HSpace.screen), child: Row(children: [
        ChoiceChip(label: const Text('All'), selected: _category == null, onSelected: (_) => setState(() => _category = null)),
        for (final category in categories) Padding(padding: const EdgeInsets.only(left: 8), child: ChoiceChip(label: Text('${notificationCategoryLabel(category)} (${folder.where((m) => notificationCategory(m) == category).length})'), selected: _category == category, onSelected: (_) => setState(() => _category = category))),
      ])),
      Expanded(child: visible.isEmpty ? EmptyState(icon: Icons.notifications_none_rounded, title: _archive ? 'No archived notices' : _unread ? 'No unread notices' : 'You’re up to date', message: 'Only notices received by this account on this device appear here.') : ListView.separated(
        padding: const EdgeInsets.all(HSpace.screen), itemCount: visible.length, separatorBuilder: (_, __) => const Gap(12),
        itemBuilder: (c, i) {
          final m = visible[i]; final id = '${m['id']}'; final read = m['read'] == true;
          return Card(color: m['important'] == true ? t.colorScheme.primaryContainer : null, child: ListTile(
            contentPadding: const EdgeInsets.all(16), leading: Icon(read ? Icons.notifications_outlined : Icons.notifications_active_outlined, color: t.colorScheme.primary),
            title: Text('${m['title'] ?? 'Notice'}', style: t.textTheme.titleSmall), subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              const Gap(4), Text('${m['body'] ?? ''}'), const Gap(8), Text('${notificationCategoryLabel(notificationCategory(m))} · ${read ? 'Read' : 'New'}${m['important'] == true ? ' · Important' : ''}', style: t.textTheme.labelSmall),
            ]),
            onTap: () async { if (!await controller.read(id, owner: owner) || !context.mounted) return; final url = '${m['url'] ?? ''}'; if (url.isNotEmpty) openLink(context, url); },
            trailing: PopupMenuButton<String>(tooltip: 'Notice actions', onSelected: (action) async {
              if (action == 'read') { await _check(controller.read(id, owner: owner)); return; }
              if (action == 'archive') { await _check(controller.archive(id, !_archive, owner: owner)); return; }
              if (action == 'delete') {
                final confirmed = await showDialog<bool>(context: context, builder: (d) => AlertDialog(title: const Text('Remove from this device?'), content: const Text('This removes your local copy of the notice. It does not delete the announcement for other people.'), actions: [TextButton(onPressed: () => Navigator.pop(d, false), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(d, true), child: const Text('Remove'))]));
                if (confirmed != true) return;
                final removed = await controller.remove(id, owner: owner);
                if (!context.mounted) return;
                if (removed == null) { showHSnack(context, 'Could not remove this notice. Please retry.', error: true); return; }
                ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: const Text('Removed from this device'), action: SnackBarAction(label: 'Undo', onPressed: () => _check(controller.restore(removed, owner: owner)))));
              }
            }, itemBuilder: (_) => [if (!read) const PopupMenuItem(value: 'read', child: Text('Mark read')), PopupMenuItem(value: 'archive', child: Text(_archive ? 'Move to inbox' : 'Archive')), const PopupMenuItem(value: 'delete', child: Text('Remove from device'))]),
          ));
        },
      )),
    ]));
  }
}

