class _ProfileScreenState extends ConsumerState<ProfileScreen> with SingleTickerProviderStateMixin {
  late final TabController _tabs;
  int _section = 0;
  @override
  void initState() {
    super.initState();
    _section = widget.initialTab.clamp(0, 2);
    _tabs = TabController(length: 3, initialIndex: _section, vsync: this)..addListener(_changed);
  }
  void _changed() { if (mounted && _section != _tabs.index) setState(() => _section = _tabs.index); }
  @override
  void didUpdateWidget(ProfileScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.initialTab != widget.initialTab) _tabs.animateTo(widget.initialTab.clamp(0, 2));
  }
  @override
  void dispose() { _tabs.removeListener(_changed); _tabs.dispose(); super.dispose(); }
